import type { RenderedFace } from '../types'

export default function CardContent({ text, rendered, className = '' }: {
  text: string; rendered?: RenderedFace; className?: string
}) {
  if (!rendered) return <div className={`whitespace-pre-wrap break-words ${className}`}>{text}</div>
  // Only accept the HTML generated by our content-preview endpoint, never card source text.
  return <div className={`rich-content ${className}`} dangerouslySetInnerHTML={{ __html: rendered.html }} />
}
